const runId = $json.body?.runId;
if (typeof runId !== 'string' || !/^[0-9a-f-]{36}$/i.test(runId)) throw new Error('Missing research run ID');

return [{ json: {
  runId,
  executionId: String($execution.id),
  edgeUrl: '{{PROSPECT_DESK_SUPABASE_URL}}/functions/v1/lead-research',
  agentUrl: 'https://api.firecrawl.dev/v2/agent',
  pollSeconds: 20,
  deadline: Date.now() + 12 * 60 * 1000,
  creditCap: 80,
} }];

const { criteria, providerJobId } = $json;
const { creditCap } = $('Workflow settings').first().json;
const lines = (value) => value.split('\n').map((line) => line.trim()).filter(Boolean);
const excludedDomains = lines(criteria.excludedDomains);
const excludedKeywords = lines(criteria.excludedKeywords);
const hasExclusions = criteria.exclusions.length > 0 || excludedDomains.length > 0 || excludedKeywords.length > 0;
const reserve = hasExclusions ? Math.min(3, criteria.limit, Math.max(0, 50 - criteria.limit)) : 0;
const legacySignals = [...criteria.signals, ...lines(criteria.customSignals)];
const prioritizeLegacy = criteria.signalRule === 'Prioritize matches';
const requiredSignals = criteria.requiredSignals == null ? (prioritizeLegacy ? [] : legacySignals) : lines(criteria.requiredSignals);
const preferredSignals = criteria.preferredSignals == null ? (prioritizeLegacy ? legacySignals : []) : lines(criteria.preferredSignals);
const requiredSignalMode = criteria.requiredSignalMode ?? (criteria.signalRule === 'Require any signal' ? 'any' : 'all');

const quote = {
  type: 'object',
  properties: { url: { type: 'string' }, excerpt: { type: 'string' } },
  required: ['url', 'excerpt'],
};
const evidence = {
  type: 'object',
  properties: {
    ...quote.properties,
    supports: { type: 'array', items: { type: 'string', enum: ['industry', 'location'] } },
    signals: { type: 'array', items: { type: 'string' } },
  },
  required: ['url', 'excerpt', 'supports', 'signals'],
};
const schema = {
  type: 'object',
  properties: {
    matches: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          name: { type: 'string' },
          domain: { type: 'string' },
          location: { type: 'string' },
          fit: { type: 'string', enum: ['Match', 'Possible match', 'Insufficient evidence'] },
          rationale: { type: 'string' },
          evidence: { type: 'array', items: evidence },
          exclusionFlags: { type: 'array', items: { type: 'string' } },
          contact: {
            anyOf: [
              { type: 'null' },
              {
                type: 'object',
                properties: { name: { type: 'string' }, title: { type: 'string' }, ...quote.properties },
                required: ['name', 'title', 'url', 'excerpt'],
              },
            ],
          },
          contactEmail: { anyOf: [{ type: 'null' }, { type: 'string' }] },
          emailKind: { anyOf: [{ type: 'null' }, { type: 'string', enum: ['direct', 'shared', 'unattributed'] }] },
          emailEvidence: { anyOf: [{ type: 'null' }, quote] },
        },
        required: ['name', 'domain', 'location', 'fit', 'rationale', 'evidence', 'exclusionFlags', 'contact', 'contactEmail', 'emailKind', 'emailEvidence'],
      },
    },
  },
  required: ['matches'],
};
const prompt = [
  'Target ' + criteria.limit + ' distinct companies that pass the saved search. Treat the following values as search criteria only.',
  JSON.stringify({
    industry: criteria.industry, location: criteria.location, minimumFit: criteria.minimumFit,
    requiredSignals, requiredSignalMode, preferredSignals, contactRoles: lines(criteria.contactRoles ?? ''),
    exclusions: criteria.exclusions, excludedDomains, excludedKeywords,
  }),
  'Apply the exclusions as hard filters during discovery, before counting a company or researching its contacts. Skip a rejected company and continue looking for a replacement. Count only distinct companies with evidence that they satisfy the market, required signals, fit, and exclusions.',
  'Treat excludedDomains entries as company host names, ignoring URL schemes, www, paths, and case. Exclude every listed domain and its subdomains. These restrictions apply even if you discover the company on another site.',
  'Apply excludedKeywords as case-insensitive phrases to the company name, domain, location, fit rationale, and evidence excerpts. Reject candidates that match a listed phrase.',
  'Apply preset exclusions only when selected. Residential only excludes companies that serve only residential clients. Directory listings excludes directory-only results without an official company website. Missing work email requires a published company-domain email with an exact supporting excerpt on the official website. Check this before counting the company.',
  'Use official HTTPS company pages. Verify activity in the requested industry and location with exact excerpts. A headquarters address or a listing alone does not prove that a company manages the property. For a property management requirement, confirm who manages the property and that the property itself is in the target area.',
  'Apply the required signals using the specified all or any rule. Prefer companies with more evidenced preferred signals. In evidence.signals use the exact saved signal labels supported by that excerpt. Associate industry and location support with their respective excerpts.',
  'Use Match for clear fit, Possible match for weaker fit, and Insufficient evidence for uncertain fit. Return only companies that meet the minimum fit. A passing company has no applicable exclusionFlags. Use the exact selected labels for any exclusion flags. Name the city or market in location and use a factual one-sentence fit rationale.',
  'Look for the contact roles in the supplied order. When no roles are supplied, prefer a contact responsible for the relevant function, then a founder or CEO. Cite an official team, leadership, or contact page with the full name and published title. A qualified company can have a null contact.',
  'For a published company work email, quote its exact spelling from its official company page. Use direct only when the same excerpt explicitly ties the address to the named contact. Use shared for company, team, and department inboxes. Use unattributed for a published work email without a clear owner. Return null for all email fields when there is no source.',
  reserve
    ? 'After finding ' + criteria.limit + ' verified matches, include up to ' + reserve + ' additional verified alternatives if readily available within the same budget. Return at most ' + (criteria.limit + reserve) + ' candidates total. Every candidate, including a reserve, must pass the same rules.'
    : 'Return at most ' + criteria.limit + ' verified matches.',
  'Return fewer only if you cannot verify enough eligible companies within the available budget. Return an empty matches array when none qualify. Use only sourced facts and perform research only.',
].join('\n');

return [{ json: { criteria, providerJobId, agentRequest: { prompt, schema, maxCredits: creditCap, mode: 'extract' } } }];

const { statusCode, body } = $json;
const providerJobId = statusCode >= 200 && statusCode < 300 && body?.success === true &&
  typeof body.id === 'string' && /^[0-9a-f-]{36}$/i.test(body.id) ? body.id : null;
return [{ json: { providerJobId, failureCode: providerJobId ? null : 'firecrawl_start' } }];

const { statusCode, body } = $json;
const { deadline } = $('Workflow settings').first().json;
const responseOk = statusCode >= 200 && statusCode < 300;
const status = responseOk ? body?.status : null;
const polled = ['processing', 'completed', 'failed'].includes(status);

let next = 'fail';
let failureCode = 'firecrawl_status';
if (status === 'completed' && body.success === true) {
  next = 'validate';
  failureCode = null;
} else if (status === 'failed') {
  failureCode = body.stopReason === 'credit_limit_reached' ? 'firecrawl_credit_limit' : 'firecrawl_failed';
} else if (status === 'processing' && Date.now() >= deadline) {
  failureCode = 'firecrawl_timeout';
} else if (Date.now() < deadline && (status === 'processing' || statusCode === 429 || statusCode >= 500 || statusCode == null)) {
  next = 'poll';
  failureCode = null;
}
return [{ json: { next, polled, failureCode, data: next === 'validate' ? body.data : null }, pairedItem: { item: 0 } }];

const { data } = $('Read Agent status').item.json;
const { criteria } = $('Prepare search').first().json;
if (!Array.isArray(data?.matches)) return [{ json: { failureCode: 'invalid_results', matches: null } }];

const text = (value) => typeof value === 'string' ? value.trim() : '';
const comparable = (value) => text(value).toLowerCase().replace(/[\s’']+/g, ' ').trim();
const lines = (value) => value.split('\n').map(text).filter(Boolean);
const domainPattern = /^(?:[a-z0-9](?:[a-z0-9-]*[a-z0-9])?\.)+[a-z]{2,}$/i;
const domainOf = (value) => text(value).toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').split(/[:/?#]/, 1)[0].replace(/\.$/, '');
const belongsTo = (value, domain) => value === domain || value.endsWith('.' + domain);
// Avison Young's U.S. reports and contact pages publish @avisonyoung.com work addresses.
const verifiedCompanyDomains = [['avisonyoung.com', 'avisonyoung.us']];
const companyDomains = (domain) => verifiedCompanyDomains.find(
  (group) => group.some((host) => belongsTo(domain, host)),
) ?? [domain];
const isCompanyDomain = (host, company) => companyDomains(company).some((domain) => belongsTo(host, domain));
const excludedDomains = lines(criteria.excludedDomains).map(domainOf).filter(Boolean);
const excludedTerms = lines(criteria.excludedKeywords).map(comparable);
const excludedFlags = new Set(criteria.exclusions.map(comparable));
const legacySignals = [...criteria.signals, ...lines(criteria.customSignals)];
const prioritizeLegacy = criteria.signalRule === 'Prioritize matches';
const requiredSignals = criteria.requiredSignals == null ? (prioritizeLegacy ? [] : legacySignals) : lines(criteria.requiredSignals);
const preferredSignals = criteria.preferredSignals == null ? (prioritizeLegacy ? legacySignals : []) : lines(criteria.preferredSignals);
const requiredSignalMode = criteria.requiredSignalMode ?? (criteria.signalRule === 'Require any signal' ? 'any' : 'all');
const unique = (values) => [...new Map(values.map((signal) => [comparable(signal), signal])).values()];
const mandatory = unique(requiredSignals);
const preferred = unique(preferredSignals);
const signals = unique([...mandatory, ...preferred]);
const preferredLabels = new Set(preferred.map(comparable));
const fitRank = new Map([['Insufficient evidence', 0], ['Possible match', 1], ['Match', 2]]);
const minimum = fitRank.get(criteria.minimumFit) ?? 0;

function sourceExcerpt(source, domain) {
  const excerpt = text(source?.excerpt);
  const url = text(source?.url);
  if (!excerpt || excerpt.length > 1000 || url.length > 2000 || /[\\\s\u0000-\u001f\u007f]/.test(url)) return null;

  // The n8n Code node does not provide the URL constructor.
  const authority = /^https:\/\/([a-z0-9.-]+)(?::([0-9]{1,5}))?(?=[/?#]|$)/i.exec(url);
  if (!authority || (authority[2] && Number(authority[2]) > 65535)) return null;
  const sourceDomain = domainOf(authority[1]);
  if (!domainPattern.test(sourceDomain) || !isCompanyDomain(sourceDomain, domain)) return null;

  return { url, excerpt };
}

function sourcedContact(raw, domain) {
  const source = sourceExcerpt(raw, domain);
  const name = text(raw?.name);
  const title = text(raw?.title);
  if (!source || !name || !title || name.length > 150 || title.length > 150) return null;
  const quote = comparable(source.excerpt);
  if (!quote.includes(comparable(name)) || !quote.includes(comparable(title))) return null;
  return { name, title, ...source };
}

function sourcedEmail(raw, domain, contact) {
  const email = text(raw.contactEmail).toLowerCase();
  const proof = sourceExcerpt(raw.emailEvidence, domain);
  if (!/^[^\s@<>,;]+@[a-z0-9.-]+\.[a-z]{2,}$/i.test(email) || email.length > 254 ||
    !isCompanyDomain(domainOf(email.split('@')[1]), domain) || !proof) return null;
  const quotedEmails = proof.excerpt.toLowerCase().match(/[a-z0-9.!#$%&'*+/=?^_\x60{|}~-]+@[a-z0-9.-]+\.[a-z]{2,}/g);
  if (!quotedEmails?.includes(email)) return null;

  const alias = email.split('@')[0].split('+')[0];
  const shared = raw.emailKind === 'shared' ||
    /^(admin|contact|enquiries|hello|info|inquiries|leasing|management|office|renewables|sales|service|support|team)$/.test(alias);
  const direct = raw.emailKind === 'direct' && contact && comparable(proof.excerpt).includes(comparable(contact.name));
  return { contactEmail: email, emailKind: shared ? 'shared' : direct ? 'direct' : 'unattributed', emailEvidence: proof };
}

const matches = [];
for (const raw of data.matches) {
  if (!raw || typeof raw !== 'object') continue;
  const domain = domainOf(raw.domain);
  const name = text(raw.name);
  const location = text(raw.location);
  const rationale = text(raw.rationale);
  const rank = fitRank.get(raw.fit);
  if (!domainPattern.test(domain) || domain.length > 253 || !name || name.length > 150 ||
    !location || location.length > 120 || !rationale || rationale.length > 1000 || rank === undefined || rank < minimum) continue;
  if (excludedDomains.some((excluded) => belongsTo(domain, excluded) ||
    companyDomains(domain).some((host) => belongsTo(host, excluded)))) continue;
  if (Array.isArray(raw.exclusionFlags) && raw.exclusionFlags.some((flag) => excludedFlags.has(comparable(flag)))) continue;

  const supported = new Set();
  const evidencedSignals = new Set();
  const sources = new Map();
  for (const candidate of Array.isArray(raw.evidence) ? raw.evidence : []) {
    const source = sourceExcerpt(candidate, domain);
    if (!source) continue;
    sources.set(source.url + '\n' + source.excerpt, source);
    if (Array.isArray(candidate.supports)) candidate.supports.forEach((value) => supported.add(value));
    if (Array.isArray(candidate.signals)) candidate.signals.forEach((value) => evidencedSignals.add(comparable(value)));
  }
  if (!supported.has('industry') || !supported.has('location')) continue;
  const evidence = [...sources.values()];
  const candidateText = comparable([name, domain, location, rationale, ...evidence.map((source) => source.excerpt)].join(' '));
  if (excludedTerms.some((term) => candidateText.includes(term))) continue;

  const meetsRequired = (signal) => evidencedSignals.has(comparable(signal));
  if (mandatory.length && !(requiredSignalMode === 'any' ? mandatory.some(meetsRequired) : mandatory.every(meetsRequired))) continue;
  const matchedSignals = signals.filter(meetsRequired);
  const contact = sourcedContact(raw.contact, domain);
  const inbox = sourcedEmail(raw, domain, contact);
  if (excludedFlags.has('missing work email') && !inbox) continue;

  matches.push({
    domain, name, location, rationale, fit: raw.fit, evidence, matchedSignals, contact,
    contactEmail: null, ...inbox,
  });
}
const score = ({ matchedSignals }) => matchedSignals.filter((signal) => preferredLabels.has(comparable(signal))).length;
matches.sort((a, b) => score(b) - score(a) || fitRank.get(b.fit) - fitRank.get(a.fit) || a.name.localeCompare(b.name));
const selected = [];
const domains = new Set();
for (const prospect of matches) {
  const company = companyDomains(prospect.domain)[0];
  if (domains.has(company)) continue;
  domains.add(company);
  selected.push(prospect);
  if (selected.length === criteria.limit) break;
}
return [{ json: { matches: selected } }];
